package com.privatezero.stadiumpad;
import java.net.*;import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;import static com.privatezero.stadiumpad.Data.*;
final class Wire implements Closeable {
 final Socket socket=new Socket();final DataInputStream in;final DataOutputStream out;
 Wire(String host,int port)throws Exception{socket.connect(new InetSocketAddress(host,port),5000);socket.setTcpNoDelay(true);socket.setSoTimeout(5000);in=new DataInputStream(socket.getInputStream());out=new DataOutputStream(socket.getOutputStream());}
 void handshake(String type)throws Exception{byte[] g=new byte[64];g[0]=(byte)255;g[8]=1;g[9]=127;g[10]=3;System.arraycopy("NULL".getBytes("US-ASCII"),0,g,12,4);out.write(g);out.flush();byte[] peer=bytes(in,64);require(peer[0]==(byte)255&&peer[9]==127&&peer[10]==3&&Arrays.equals(Arrays.copyOfRange(g,12,32),Arrays.copyOfRange(peer,12,32)),"Unsupported Stadium authentication");ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream m=new DataOutputStream(b);m.writeByte(5);m.writeBytes("READY");m.writeByte(11);m.writeBytes("Socket-Type");m.writeInt(type.length());m.writeBytes(type);if(type.equals("DEALER")){m.writeByte(8);m.writeBytes("Identity");m.writeInt(0);}send(4,b.toByteArray());Frame f=frame();DataInputStream r=new DataInputStream(new ByteArrayInputStream(f.bytes));require((f.flags&4)!=0&&new String(bytes(r,r.readUnsignedByte()),"UTF-8").equals("READY"),"Stadium rejected session");String t="";while(r.available()>0){String k=new String(bytes(r,r.readUnsignedByte()),"UTF-8"),v=new String(bytes(r,r.readInt()),"UTF-8");if(k.equals("Socket-Type"))t=v;}require(type.equals("SUB")?Arrays.asList("PUB","XPUB","ROUTER").contains(t):t.equals("ROUTER"),"Unexpected socket type");if(type.equals("SUB"))send(0,new byte[]{1});}
 synchronized void send(int flags,byte[] bytes)throws Exception{require(bytes.length<=LIMIT,"Frame too large");if(bytes.length<256){out.writeByte(flags);out.writeByte(bytes.length);}else{out.writeByte(flags|2);out.writeLong(bytes.length);}out.write(bytes);out.flush();}
 static final class Frame {final int flags;final byte[] bytes;Frame(int f,byte[]b){flags=f;bytes=b;}}
 Frame frame()throws Exception{int f=in.readUnsignedByte();require((f&248)==0,"Invalid frame flags");long n=(f&2)!=0?in.readLong():in.readUnsignedByte();require(n>=0&&n<=LIMIT,"Frame too large");return new Frame(f,bytes(in,(int)n));}
 public void close(){try{socket.close();}catch(Exception ignored){}}
}
